-- sql/lab/seed.sql: synthetic practice data for the day-7 exercises. Never load it into a
-- real database. It is generated by formula, not at random, so every run gives the same rows,
-- and ON CONFLICT makes a second run add nothing.
--
--   parcels      20,000, numbered PX00000001 upwards
--   hubs         1 to 5 stops per parcel; every 10th parcel has none (exercise 5)
--   scan_events  1 to 4 scans per stop
--   A rare "Islands" region totals less than 1000, so exercise 6's filter removes something.

BEGIN;

INSERT INTO parcels (tracking_no, recipient_name, status, created_at)
SELECT
    'PX' || lpad(g::text, 8, '0'),
    (ARRAY['Asha', 'Bram', 'Chen', 'Dara', 'Elio', 'Farah', 'Goran', 'Hana', 'Ivo', 'Jun'])[1 + g % 10]
        || ' ' ||
    (ARRAY['Alder', 'Brook', 'Cole', 'Dunn', 'Ellis', 'Frost', 'Grove', 'Hale', 'Ivey', 'Joyce'])[1 + (g / 10) % 10],
    CASE
        WHEN g % 20 < 6  THEN 'active'
        WHEN g % 20 < 17 THEN 'delivered'
        WHEN g % 20 < 19 THEN 'returned'
        ELSE 'cancelled'
    END,
    TIMESTAMPTZ '2026-01-01 00:00:00+00' + g * INTERVAL '20 minutes'
FROM generate_series(1, 20000) AS g
ON CONFLICT (tracking_no) DO NOTHING;

INSERT INTO hubs (parent_id, name, label, amount)
SELECT p.id, h.name, h.label, 50 + (n.g * 37 + s * 101) % 850
FROM parcels AS p
CROSS JOIN LATERAL (SELECT substr(p.tracking_no, 3)::int AS g) AS n
CROSS JOIN LATERAL generate_series(1, 1 + n.g % 5) AS s
JOIN (VALUES
        (0, 'Kochi Hub', 'South'),
        (1, 'Chennai Hub', 'South'),
        (2, 'Bengaluru Hub', 'South'),
        (3, 'Mumbai Hub', 'West'),
        (4, 'Pune Hub', 'West'),
        (5, 'Delhi Hub', 'North'),
        (6, 'Kolkata Hub', 'East')
     ) AS h (slot, name, label) ON h.slot = (n.g + s) % 7
WHERE p.tracking_no LIKE 'PX%' AND n.g % 10 <> 0
ON CONFLICT (parent_id, name) DO NOTHING;

INSERT INTO hubs (parent_id, name, label, amount)
SELECT p.id, 'Port Blair Hub', 'Islands', 40
FROM parcels AS p
WHERE p.tracking_no LIKE 'PX%' AND substr(p.tracking_no, 3)::int % 997 = 0
ON CONFLICT (parent_id, name) DO NOTHING;

INSERT INTO scan_events (parent_id, event, occurred_at)
SELECT h.id, e.event, p.created_at + (h.id % 97) * INTERVAL '1 hour' + e.step * INTERVAL '20 minutes'
FROM hubs AS h
JOIN parcels AS p ON p.id = h.parent_id
JOIN (VALUES (1, 'arrived'), (2, 'sorted'), (3, 'departed'), (4, 'exception')) AS e (step, event)
    ON e.step <= 1 + h.id % 4
WHERE p.tracking_no LIKE 'PX%'
ON CONFLICT (parent_id, occurred_at, event) DO NOTHING;

COMMIT;

-- Fresh statistics, so EXPLAIN plans reflect the real row counts.
ANALYZE parcels, hubs, scan_events;
